    {
      "name": "Polynomial.coeff_bdd_of_roots_le",
      "module_name": "Mathlib.Topology.Algebra.Polynomial",
      "kind": "theorem",
      "type": "∀ {F : Type u_3} {K : Type u_4} [inst : CommRing F] [inst_1 : NormedField K] {B : ℝ} {d : ℕ} (f : F →+* K)\n  {p : Polynomial F},\n  p.Monic →\n    (Polynomial.map f p).Splits →\n      p.natDegree ≤ d →\n        (∀ z ∈ (Polynomial.map f p).roots, ‖z‖ ≤ B) →\n          ∀ (i : ℕ), ‖(Polynomial.map f p).coeff i‖ ≤ max B 1 ^ d * ↑(d.choose (d / 2))"
    },
    {
      "name": "Polynomial.coeff_le_of_roots_le",
      "module_name": "Mathlib.Topology.Algebra.Polynomial",
      "kind": "theorem",
      "type": "∀ {F : Type u_3} {K : Type u_4} [inst : CommRing F] [inst_1 : NormedField K] {p : Polynomial F} {f : F →+* K} {B : ℝ}\n  (i : ℕ),\n  p.Monic →\n    (Polynomial.map f p).Splits →\n      (∀ z ∈ (Polynomial.map f p).roots, ‖z‖ ≤ B) →\n        ‖(Polynomial.map f p).coeff i‖ ≤ B ^ (p.natDegree - i) * ↑(p.natDegree.choose i)"
    },
    {
      "name": "Polynomial.Chebyshev.coeff_le_of_forall_abs_le_one",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Trigonometric.Chebyshev.Extremal",
      "kind": "theorem",
      "type": "∀ {n : ℕ} {P : Polynomial ℝ},\n  P.degree ≤ ↑n → (∀ x ∈ Set.Icc (-1) 1, |Polynomial.eval x P| ≤ 1) → P.coeff n ≤ 2 ^ (n - 1)"
    },
    {
      "name": "Ideal.leadingCoeffNth_mono",
      "module_name": "Mathlib.RingTheory.Polynomial.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : CommSemiring R] (I : Ideal (Polynomial R)) {m n : ℕ},\n  m ≤ n → I.leadingCoeffNth m ≤ I.leadingCoeffNth n"
    },
    {
      "name": "Polynomial.cauchyBound_zero",
      "module_name": "Mathlib.Analysis.Polynomial.CauchyBound",
      "kind": "theorem",
      "type": "∀ {K : Type u_1} [inst : NormedDivisionRing K], Polynomial.cauchyBound 0 = 1"
    }
  ]
}

