    },
    {
      "name": "MonotoneOn.csSup_eq_of_subset_of_forall_exists_le",
      "module_name": "Mathlib.Order.ConditionallyCompleteLattice.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : Type u_2} [inst : Preorder α] [inst_1 : ConditionallyCompleteLattice β] {f : α → β} {s t : Set α},\n  BddAbove (f '' t) → MonotoneOn f t → s ⊆ t → (∀ y ∈ t, ∃ x ∈ s, y ≤ x) → sSup (f '' s) = sSup (f '' t)"
    },
    {
      "name": "csSup_le_csSup'",
      "module_name": "Mathlib.Order.ConditionallyCompleteLattice.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} [inst : ConditionallyCompleteLinearOrderBot α] {s t : Set α}, BddAbove t → s ⊆ t → sSup s ≤ sSup t"
    },
    {
      "name": "subset_sSup_of_within",
      "module_name": "Mathlib.Order.CompleteLatticeIntervals",
      "kind": "theorem",
      "type": "∀ {α : Type u_2} (s : Set α) [inst : Preorder α] [inst_1 : SupSet α] [inst_2 : Inhabited ↑s] {t : Set ↑s},\n  t.Nonempty → BddAbove t → sSup (Subtype.val '' t) ∈ s → sSup (Subtype.val '' t) = ↑(sSup t)"
    }
  ]
}

